create table if not exists public.dd_system_of_record_registry (id uuid primary key default gen_random_uuid(), data_domain text not null unique, system_name text not null, authority_level text not null default 'PRIMARY', notes text, status text not null default 'LOCKED', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create table if not exists public.dd_operating_matrix_registry (id uuid primary key default gen_random_uuid(), matrix_number integer not null unique, matrix_name text not null unique, scope text, status text not null default 'LOCKED', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create table if not exists public.dd_document_governance (id uuid primary key default gen_random_uuid(), document_type text not null unique, authority_role text not null, status text not null default 'AUDIT_SOURCE', print_status text not null default 'NOT_READY', reconciliation_required boolean not null default true, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); insert into dd_system_of_record_registry(data_domain,system_name,notes) values ('COMMERCIAL_ARCHITECTURE','DANI / Supabase','DANI remains commercial authority; external tools are integrations.'),('MASTER_SERVICE_UNIVERSE','DANI / Supabase','Includes DANI service evidence, provider evidence, historical sources and unresolved records.'),('PROVIDER_CAPABILITY','DANI / Supabase','Provider offerings are evidence/capacity, not commercial ownership.'),('FULFILLMENT','DANI / Supabase','Qualified provider, authorization, matching, dispatch, completion and settlement orchestration.'),('CUSTOMER_RELATIONSHIPS','HubSpot','CRM/relationship layer; does not own commercial service definitions.'),('PAYMENTS','Stripe','Financial transaction authority.'),('PRODUCT_COMMERCE','Shopify','Product commerce layer.'),('WORKFORCE_TIME','Jibble','Time/attendance integration.'),('FIELD_SERVICE','Jobber / Housecall Pro','Field-service integrations; DANI remains architectural authority.'),('LEAD_ACQUISITION','Thumbtack','Marketplace/lead acquisition integration.'),('ANALYTICS','PostHog','Product and operational analytics.'),('APPLICATION_CODE','GitHub','Source control.'),('APPLICATION_DEPLOYMENT','Vercel','Deployment.'),('CUSTOMER_COMMUNICATIONS','Resend / Twilio','Transactional email and SMS.') on conflict(data_domain) do update set system_name=excluded.system_name,notes=excluded.notes,status='LOCKED',updated_at=now(); insert into dd_operating_matrix_registry(matrix_number,matrix_name,scope) values (1,'Master Commercial Catalog Matrix','Canonical commercial universe'),(2,'Commercial Channel Matrix','Five channels and CH01 subchannels'),(3,'Customer/Buyer/Use-Case Matrix','Customer, buyer and use-case relationships'),(4,'Master Pricing Matrix','Customer pricing'),(5,'Pricing Rules/Engine Matrix','Pricing logic'),(6,'Service Execution Matrix','Execution requirements'),(7,'Package/Membership/Retainer Matrix','Commercial forms beyond standalone services'),(8,'Capability/Provider Matrix','Provider capability and qualification'),(9,'Dispatch/Matching Matrix','Fulfillment matching and dispatch'),(10,'Revenue/Unit Economics Matrix','Customer revenue, provider pay and contribution economics'),(11,'Cross-Division/Cross-Sell Matrix','Cross-sell and relationship architecture') on conflict(matrix_number) do update set matrix_name=excluded.matrix_name,scope=excluded.scope,status='LOCKED',updated_at=now(); insert into dd_document_governance(document_type,authority_role,notes) values ('VENDOR_PACKET','COMMERCIAL_EVIDENCE','Must reconcile to Master Service Universe before READY_FOR_PRINT.'),('RESIDENT_WELCOME_PACKET','CUSTOMER_EXPERIENCE_EVIDENCE','Must reconcile to Master Service Universe before READY_FOR_PRINT.'),('RESIDENT_GUIDE','CUSTOMER_EXPERIENCE_EVIDENCE','Must reconcile to Master Service Universe before READY_FOR_PRINT.') on conflict(document_type) do update set authority_role=excluded.authority_role,notes=excluded.notes,reconciliation_required=true,updated_at=now();